'use strict';
const t=OrionI18n.t;
let resetResult=null;
function renderHub(){document.getElementById('resetStatus').textContent=resetResult===null?'':resetResult?t('All sigils have been reset. Every game now has a different challenge.','所有符印已重設，每個遊戲都換上了不同的挑戰。'):t('The browser could not save the reset. Your collection has not been changed.','瀏覽器無法儲存重設結果。你的符印收藏未有更改。');const earned=OrionProgress.read().sigils;document.getElementById('availability').textContent=t(`${ORION_MISSIONS.filter(m=>m.href).length} missions available · ${ORION_MISSIONS.length} stories to explore`,`${ORION_MISSIONS.filter(m=>m.href).length} 個任務已開放 · ${ORION_MISSIONS.length} 個故事等待探索`);document.getElementById('total').textContent=ORION_MISSIONS.filter(m=>earned.includes(m.sigil)).length;document.getElementById('sigils').innerHTML=ORION_MISSIONS.map(m=>{const yes=earned.includes(m.sigil),name=t(m.sigilEnglish,m.sigilName),state=yes?t('Collected','已收藏'):t('Not collected','未收藏');return `<span class="sigil-slot"><button type="button" class="sigil ${yes?'earned':''}" aria-label="${name}: ${state}" aria-describedby="sigil-tip-${m.sigil}"><b aria-hidden="true">${m.symbol}</b>${yes?'<i aria-hidden="true">✓</i>':''}</button><span class="sigil-tooltip" id="sigil-tip-${m.sigil}" role="tooltip"><strong>${name} · ${state}</strong><span>${t(m.english,m.title)}</span><span>${t(m.storyEnglish,m.story)}</span></span></span>`}).join('');document.getElementById('missions').innerHTML=ORION_MISSIONS.map(m=>`<article class="mission ${m.href?'available':''}"><div class="mission-top"><span class="symbol" aria-hidden="true">${m.symbol}</span><span class="badge">${m.href?t('Available','已開放'):t('Coming soon','即將登場')}</span></div><h3>${t(m.english,m.title)}</h3><p class="story">${t(m.storyEnglish,m.story)}</p><div class="topic">${t(m.topic.split(' / ')[0],m.topic.split(' / ')[1])}</div><div class="card-footer"><span>${earned.includes(m.sigil)?t('✦ Collected','✦ 已收藏'):t(m.sigilEnglish+' Sigil',m.sigilName+'符印')}</span>${m.href?`<a href="${m.href}">${earned.includes(m.sigil)?t('Play again','再次探索'):t('Start mission','開始任務')} ↗</a>`:`<span class="soon">${t('In preparation','準備中')}</span>`}</div></article>`).join('');}
window.addEventListener('orion-language',renderHub);window.addEventListener('storage',renderHub);OrionI18n.apply();

document.getElementById('resetSigils').addEventListener('click',()=>{if(!window.confirm(t('Reset all collected sigils in this browser? This clears the entire collection, including future missions. Every game will get a different challenge. Your language choice will stay unchanged.','確定要重設這個瀏覽器內的所有符印嗎？這會清空整個收藏，包括日後新增任務的符印，每個遊戲也會換上不同的挑戰，但不會更改語言選擇。')))return;resetResult=OrionProgress.reset();renderHub();});

// Hover, keyboard focus and touch share the same optional description.
const sigilTray=document.getElementById('sigils');
function placeSigilTip(slot){const tray=sigilTray.getBoundingClientRect(),icon=slot.getBoundingClientRect(),tip=slot.querySelector('.sigil-tooltip');const width=Math.min(360,tray.width);tip.style.left=Math.max(0,Math.min(icon.left-tray.left+icon.width/2-width/2,tray.width-width))+'px';slot.classList.remove('dismissed');}
sigilTray.addEventListener('keydown',event=>{if(event.key==='Escape'){const slot=event.target.closest('.sigil-slot');if(slot)slot.classList.add('dismissed');}});
sigilTray.addEventListener('focusin',event=>{const slot=event.target.closest('.sigil-slot');if(slot)placeSigilTip(slot);});
sigilTray.addEventListener('pointerover',event=>{const slot=event.target.closest('.sigil-slot');if(slot&&!slot.contains(event.relatedTarget))placeSigilTip(slot);});
sigilTray.addEventListener('click',event=>{const button=event.target.closest('button.sigil');if(button){placeSigilTip(button.closest('.sigil-slot'));button.focus();}});
window.addEventListener('pointerdown',event=>{if(!sigilTray.contains(event.target)){sigilTray.querySelectorAll('.sigil-slot').forEach(slot=>slot.classList.add('dismissed'));}});
